def hull_cells(cells):
    pts=np.array([(r+dr,c+dc) for r,c in cells for dr,dc in [(0,0),(0,1),(1,0),(1,1)]])
    h=ConvexHull(pts)
    out=[]
    for r in range(int(pts[:,0].min()),int(pts[:,0].max())):
      for c in range(int(pts[:,1].min()),int(pts[:,1].max())):
       if np.all(h.equations[:,:2]@np.array([r+.5,c+.5])+h.equations[:,2] <= 1e-8): out.append((r,c))
    return out
